namespace NHAMBS.Cht

open System.IO
open FSharp.Data

/// Typed view of the CMHC list of outstanding CHT debt issues.
///
/// The provider reads `schema/cmhc-cht-debt-issues.provider.schema.json`, a
/// flattened copy of the real Draft 2020-12 schema. The copy is generated by
/// `generate-provider-schema.fsx` because FSharp.Data's schema reader does not
/// resolve `$ref`. The real schema remains the source of truth and is embedded
/// in this assembly for validation by `DebtIssuesSchema.validate`.
type DebtIssues =
    JsonProvider<
        "",
        Schema="schema/cmhc-cht-debt-issues.provider.schema.json",
        EmbeddedResource="NHAMBS.Cht, NHAMBS.Cht.schema.cmhc-cht-debt-issues.provider.schema.json"
     >

[<RequireQualifiedAccess>]
module DebtIssues =

    /// Parse JSON that is already known to match the debt issues schema.
    let parse (json: string) : DebtIssues.Root = DebtIssues.Parse json

    /// Validate JSON against the embedded schema, then parse it.
    let parseValidated (json: string) : Result<DebtIssues.Root, ValidationError list> =
        match DebtIssuesSchema.validate json with
        | Error errors -> Error errors
        | Ok _ -> Ok(parse json)

    /// Load one debt issues file, validate it, and return its typed representation.
    let load (path: string) : Result<DebtIssues.Root, ValidationError list> = File.ReadAllText path |> parseValidated

    /// Load a sequence of debt issues files. Each result keeps its source path.
    let loadMany (paths: string seq) =
        paths |> Seq.map (fun path -> path, load path) |> Seq.toArray

    /// Load every `*.json` file directly under a directory.
    let loadDirectory (directory: string) =
        Directory.EnumerateFiles(directory, "*.json") |> loadMany

    /// Small projection that is useful when indexing a CHT snapshot.
    let summary (issues: DebtIssues.Root) =
        {|
            AsOfDate = issues.AsOfDate
            IssueCount = issues.Issues.Length
            TotalIssuanceMillions = issues.Issues |> Array.sumBy (fun issue -> issue.TotalIssuance)
            OutstandingMillions = issues.Issues |> Array.sumBy (fun issue -> issue.Outstanding)
        |}
